#include <optional>
#include <string>
#include <vector>

struct User { int id; std::string name; };
struct Repo { std::vector<User> users; };

// Contract:
//   Borrows repo (read-only, not stored). No mutation.
//   Returns the user with this id, or std::nullopt if none.
//   O(n) in repo size. May throw std::bad_alloc when copying the result.
std::optional<User> find_user(const Repo& repo, int id) {
    for (const auto& u : repo.users) {
        if (u.id == id) return u;      // copy out.
    }
    return std::nullopt;               // explicit "not found".
}

// Precondition stated in the contract, checked in debug builds.
// Requires: !scores.empty().
double mean(const std::vector<int>& scores);
```

